create or replace function epic.reset_demo_data()
returns void
language plpgsql
security definer
set search_path = epic, pg_temp
as $$
begin
  truncate table epic.practitioner_role, epic.diagnostic_report, epic.procedure, epic.allergy_intolerance, epic.observation, epic.medication_request, epic.condition, epic.encounter, epic.patient, epic.practitioner cascade;

  
  
  
  
  
  
  
  
  
  
  end;
$$;

revoke execute on function epic.reset_demo_data() from public, anon, authenticated;
grant execute on function epic.reset_demo_data() to service_role;

select epic.reset_demo_data();
